progress-tracking.signature:
pub fn progress(&self) -> u64 {
    self.progress.load(Ordering::Relaxed)
}

pub fn progress_percentage(&self) -> f64 {
    (self.progress() as f64 / self.total_docs as f64) * 100.0
}

